create table if not exists automation_rules(id uuid primary key default gen_random_uuid(),venue_id uuid not null references venues(id) on delete cascade,name text not null,trigger_type text not null,conditions jsonb not null default '{}'::jsonb,actions jsonb not null default '[]'::jsonb,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists automation_runs(id uuid primary key default gen_random_uuid(),venue_id uuid not null references venues(id) on delete cascade,rule_id uuid references automation_rules(id) on delete set null,status text not null,input jsonb not null default '{}'::jsonb,output jsonb not null default '{}'::jsonb,error_message text,created_at timestamptz not null default now());